package domain

import (
	"database/sql"
	"fmt"
	"path/filepath"
	"strconv"
)

// CheckMigrationSafety is the startup hook proposed for Service.New. Existing
// populated authority must first be backed up using its matching program, then
// migrated and verified in an isolated RestoreBackup copy. No environment flag
// or operator assertion silently authorizes an in-place migration.
func CheckMigrationSafety(db *sql.DB, files []string) error {
	var exists int
	if e := db.QueryRow("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='domain_objects'").Scan(&exists); e != nil {
		return e
	}
	if exists == 0 {
		return nil
	}
	var count int
	if e := db.QueryRow("SELECT count(*) FROM domain_objects").Scan(&count); e != nil {
		return e
	}
	if count == 0 {
		return nil
	}
	for _, file := range files {
		base := filepath.Base(file)
		if len(base) < 4 {
			return fmt.Errorf("MIGRATION_FILENAME_INVALID")
		}
		v, e := strconv.Atoi(base[:4])
		if e != nil {
			return e
		}
		var applied int
		if e = db.QueryRow("SELECT count(*) FROM schema_migrations WHERE version=?", v).Scan(&applied); e != nil {
			return e
		}
		if applied == 0 {
			return fmt.Errorf("MIGRATION_PREBACKUP_REQUIRED: back up with matching program and verify an isolated restore before migration %d", v)
		}
	}
	return nil
}
package domain

import (
	"context"
	"database/sql"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

// Existing authority requires matching-program backup and isolated migration.
// This is a read-only domain guard; store.Open may already have selected WAL.
func CheckMigrationSafety(db *sql.DB, files []string) error {
	applied, e := checkMigrationInventory(db, files)
	if e != nil {
		return e
	}
	populated, e := migrationAuthorityPresent(db)
	if e != nil {
		return e
	}
	if !populated {
		return nil
	}
	if applied != len(files) {
		return fmt.Errorf("MIGRATION_PREBACKUP_REQUIRED: back up with matching program and verify an isolated restore before migration %d", applied+1)
	}
	raw, e := os.ReadFile(filepath.Join(filepath.Dir(files[0]), "next_v24_sessions.sql"))
	if e != nil || Digest(raw) != upgradeQueueSessionHash {
		return fmt.Errorf("MIGRATION_ADDITIVE_SOURCE")
	}
	expected, e := sql.Open("sqlite", ":memory:")
	if e != nil {
		return e
	}
	defer expected.Close()
	expected.SetMaxOpenConns(1)
	if _, e = expected.Exec(string(raw)); e != nil {
		return e
	}
	if e = installClientSessionFence(context.Background(), expected, false); e != nil {
		return e
	}
	want, e := migrationSessionSchema(expected)
	if e != nil {
		return e
	}
	got, e := migrationSessionSchema(db)
	if e != nil {
		return e
	}
	if Hash(got) != Hash(want) {
		return fmt.Errorf("MIGRATION_PREBACKUP_REQUIRED: additive session schema or fence differs")
	}
	return nil
}

func checkMigrationInventory(db *sql.DB, files []string) (int, error) {
	if len(files) == 0 || len(files) > 24 {
		return 0, fmt.Errorf("MIGRATION_SOURCE_INVENTORY")
	}
	for i, file := range files {
		base := filepath.Base(file)
		if len(base) < 6 || base[4] != '_' {
			return 0, fmt.Errorf("MIGRATION_FILENAME_INVALID")
		}
		v, e := strconv.Atoi(base[:4])
		if e != nil || v != i+1 {
			return 0, fmt.Errorf("MIGRATION_SOURCE_INVENTORY")
		}
	}
	var exists int
	if e := db.QueryRow("SELECT count(*) FROM sqlite_master WHERE type='table' AND name='schema_migrations'").Scan(&exists); e != nil {
		return 0, e
	}
	if exists == 0 {
		return 0, fmt.Errorf("MIGRATION_BOOTSTRAP_REQUIRED")
	}
	rows, e := db.Query("SELECT version,typeof(version) FROM schema_migrations ORDER BY version")
	if e != nil {
		return 0, e
	}
	defer rows.Close()
	n := 0
	for rows.Next() {
		var v int
		var kind string
		if e = rows.Scan(&v, &kind); e != nil {
			return 0, e
		}
		n++
		if kind != "integer" || v != n || v > len(files) {
			return 0, fmt.Errorf("MIGRATION_UNSUPPORTED_OR_GAPPED_VERSION")
		}
	}
	if e = rows.Err(); e != nil {
		return 0, e
	}
	if n == 0 {
		return 0, fmt.Errorf("MIGRATION_BOOTSTRAP_REQUIRED")
	}
	return n, nil
}

func migrationAuthorityPresent(db *sql.DB) (bool, error) {
	rows, e := db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
	if e != nil {
		return false, e
	}
	names := []string{}
	for rows.Next() {
		var name string
		if e = rows.Scan(&name); e != nil {
			rows.Close()
			return false, e
		}
		names = append(names, name)
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return false, e
	}
	for _, name := range names {
		if name == "schema_migrations" {
			continue
		}
		query := `SELECT count(*) FROM "` + strings.ReplaceAll(name, `"`, `""`) + `"`
		// Only the exact source-defined mutex seed is structural, not authority.
		if name == "resource_write_lock" {
			query += " WHERE id<>1 OR value<>0"
		}
		var n int
		if e = db.QueryRow(query).Scan(&n); e != nil {
			return false, e
		}
		if n != 0 {
			return true, nil
		}
	}
	return false, nil
}

func migrationSessionSchema(db *sql.DB) ([]Object, error) {
	rows, e := db.Query(`SELECT type,name,tbl_name,sql FROM sqlite_master WHERE tbl_name IN ('client_sessions','backup_restore_barriers') AND sql IS NOT NULL ORDER BY type,name`)
	if e != nil {
		return nil, e
	}
	defer rows.Close()
	result := []Object{}
	for rows.Next() {
		var typ, name, table, raw string
		if e = rows.Scan(&typ, &name, &table, &raw); e != nil {
			return nil, e
		}
		result = append(result, Object{"type": typ, "name": name, "table": table, "sql": raw})
	}
	return result, rows.Err()
}
// backup is a local administrative command; it starts no server or worker.
package main

import (
	"context"
	"crypto/rand"
	"encoding/json"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"researchos.local/research-os/internal/domain"
	"researchos.local/research-os/internal/store"
	"strconv"
	"strings"
)

func main() {
	if e := run(); e != nil {
		fmt.Fprintln(os.Stderr, e)
		os.Exit(1)
	}
}
func run() error {
	if len(os.Args) < 2 {
		return fmt.Errorf("usage: backup keygen|create|export|restore|upgrade-local [flags]")
	}
	command := os.Args[1]
	f := flag.NewFlagSet(command, flag.ContinueOnError)
	source := f.String("db", "", "existing source SQLite database")
	backup := f.String("backup", "", "existing encrypted backup directory")
	out := f.String("out", "", "new destination (must not exist)")
	keyfile := f.String("key-file", "", "separate recovery key file; never command-line key bytes")
	root := f.String("root", ".", "matching application repository root")
	sourceRoot := f.String("source-root", "", "upgrade: exact schema13 release root")
	sourceProgram := f.String("source-program", "", "upgrade: preserved matching old program")
	targetProgram := f.String("target-program", "", "upgrade: reviewed target program")
	plan := f.String("plan", "", "upgrade: schema13-to14-remote-access-v1 or schema13-to20-research-runtime-v1 (exact releases only)")
	if e := f.Parse(os.Args[2:]); e != nil {
		return e
	}
	if f.NArg() != 0 {
		return fmt.Errorf("unexpected positional arguments")
	}
	if *keyfile == "" {
		return fmt.Errorf("--key-file required")
	}
	if command == "keygen" {
		key := make([]byte, 32)
		if _, e := rand.Read(key); e != nil {
			return e
		}
		f, e := os.OpenFile(*keyfile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
		if e != nil {
			return e
		}
		defer f.Close()
		if _, e = f.Write(key); e != nil {
			return e
		}
		if e = f.Sync(); e != nil {
			return e
		}
		fmt.Println(`{"status":"KEY_CREATED_SEPARATELY","key_bytes_printed":false}`)
		return nil
	}
	if command != "create" && command != "export" && command != "restore" && command != "upgrade-local" {
		return fmt.Errorf("unknown command")
	}
	if *out == "" {
		return fmt.Errorf("--out required")
	}
	if command == "upgrade-local" {
		r, e := domain.UpgradeLocal(context.Background(), domain.LocalUpgradeOptions{
			Source: *source, Snapshot: *backup, Destination: *out, KeyFile: *keyfile,
			SourceRoot: *sourceRoot, TargetRoot: *root, SourceProgram: *sourceProgram,
			TargetProgram: *targetProgram, Plan: *plan,
		})
		if e != nil {
			return e
		}
		return json.NewEncoder(os.Stdout).Encode(r)
	}
	keyPath, e := filepath.Abs(*keyfile)
	if e != nil {
		return e
	}
	for _, dir := range []string{*out, *backup} {
		if dir == "" {
			continue
		}
		abs, e := filepath.Abs(dir)
		if e != nil {
			return e
		}
		rel, e := filepath.Rel(abs, keyPath)
		if e == nil && filepath.IsLocal(rel) {
			return fmt.Errorf("KEY_MUST_BE_OUTSIDE_BACKUP_AND_RESTORE")
		}
	}
	key, e := os.ReadFile(*keyfile)
	if e != nil || len(key) != 32 {
		return fmt.Errorf("BACKUP_KEY_UNAVAILABLE")
	}
	defer clear(key)
	contracts, e := domain.LoadContracts(filepath.Join(*root, "spec/v2.0/contracts"))
	if e != nil {
		return e
	}
	ctx := context.Background()
	if command == "restore" {
		if *backup == "" {
			return fmt.Errorf("--backup required")
		}
		files, e := filepath.Glob(filepath.Join(*root, "migrations/sqlite/[0-9][0-9][0-9][0-9]_*.sql"))
		if e != nil {
			return e
		}
		versions := []int{}
		for _, file := range files {
			v, e := strconv.Atoi(filepath.Base(file)[:4])
			if e != nil {
				return e
			}
			versions = append(versions, v)
		}
		r, e := domain.RestoreBackup(ctx, *backup, *out, domain.RestoreOptions{Key: key, SupportedMigrations: versions, Contracts: contracts})
		if e != nil {
			return e
		}
		return json.NewEncoder(os.Stdout).Encode(r)
	}
	if *source == "" {
		return fmt.Errorf("--db required")
	}
	st, e := os.Stat(*source)
	if e != nil || !st.Mode().IsRegular() {
		return fmt.Errorf("existing regular source database required")
	}
	// Refuse ambiguous URI DSNs; --db is an ordinary local file path.
	if strings.Contains(*source, "?") {
		return fmt.Errorf("SQLite URI parameters prohibited")
	}
	db, e := store.Open(*source)
	if e != nil {
		return e
	}
	defer db.Close()
	s := &domain.Service{DB: db, Contracts: contracts}
	m, e := s.CreateBackup(ctx, *out, key)
	if e != nil {
		return e
	}
	return json.NewEncoder(os.Stdout).Encode(m)
}
